const STAGES = [
  { key: "pending", label: "待投递" },
  { key: "applied", label: "已投递" },
  { key: "interview", label: "面试中" },
  { key: "closed", label: "已结束" }
];
const STAGE_KEYS = STAGES.map((s) => s.key);
const STAGE_LABEL = STAGES.reduce((acc, s) => {
  acc[s.key] = s.label;
  return acc;
}, {});
const STORE_KEY = "jobApplications";

const el = {
  totalCount: document.querySelector('[data-role="total-count"]'),
  statsGrid: document.querySelector('[data-role="stats-grid"]'),
  form: document.querySelector('[data-role="record-form"]'),
  formTitle: document.querySelector('[data-role="form-title"]'),
  company: document.querySelector('[data-role="input-company"]'),
  position: document.querySelector('[data-role="input-position"]'),
  date: document.querySelector('[data-role="input-date"]'),
  stage: document.querySelector('[data-role="input-stage"]'),
  note: document.querySelector('[data-role="input-note"]'),
  formError: document.querySelector('[data-role="form-error"]'),
  submitBtn: document.querySelector('[data-role="submit-btn"]'),
  cancelBtn: document.querySelector('[data-role="cancel-btn"]'),
  listCount: document.querySelector('[data-role="list-count"]'),
  recordList: document.querySelector('[data-role="record-list"]'),
  emptyHint: document.querySelector('[data-role="empty-hint"]'),
  chips: Array.from(document.querySelectorAll(".chip[data-filter]")),
  dialogMask: document.querySelector('[data-role="dialog-mask"]'),
  dialogTitle: document.querySelector('[data-role="dialog-title"]'),
  dialogText: document.querySelector('[data-role="dialog-text"]'),
  dialogCancel: document.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: document.querySelector('[data-role="dialog-confirm"]')
};

let state = null;
let records = [];
let filterStage = "all";
let editingId = null;
let pendingDeleteId = null;
let dialogResolver = null;

function normalizeStage(value) {
  return STAGE_KEYS.indexOf(value) >= 0 ? value : "pending";
}

function normalizeRecord(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const record = Object.assign({}, source);
  record.id = typeof source.id === "string" && source.id ? source.id : createId();
  record.company = typeof source.company === "string" ? source.company : "";
  record.position = typeof source.position === "string" ? source.position : "";
  record.applyDate = typeof source.applyDate === "string" ? source.applyDate : "";
  record.stage = normalizeStage(source.stage);
  record.note = typeof source.note === "string" ? source.note : "";
  return record;
}

function createId() {
  return "rec-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
}

function todayISO() {
  const now = new Date();
  const m = String(now.getMonth() + 1).padStart(2, "0");
  const d = String(now.getDate()).padStart(2, "0");
  return now.getFullYear() + "-" + m + "-" + d;
}

function formatDate(value) {
  if (!value) return "未填写日期";
  const parts = String(value).split("-");
  if (parts.length !== 3) return String(value);
  return parts[0] + " 年 " + Number(parts[1]) + " 月 " + Number(parts[2]) + " 日";
}

function showFormError(message) {
  if (!message) {
    el.formError.hidden = true;
    el.formError.textContent = "";
    return;
  }
  el.formError.hidden = false;
  el.formError.textContent = message;
}

function computeStats() {
  const counts = STAGE_KEYS.reduce((acc, key) => {
    acc[key] = 0;
    return acc;
  }, {});
  records.forEach((record) => {
    const key = normalizeStage(record.stage);
    counts[key] += 1;
  });
  const total = STAGE_KEYS.reduce((sum, key) => sum + counts[key], 0);
  return { counts, total };
}

function renderStats() {
  const stats = computeStats();
  el.totalCount.textContent = String(stats.total);
  el.statsGrid.textContent = "";
  STAGES.forEach((stage) => {
    const li = document.createElement("li");
    li.className = "stats-item";
    li.setAttribute("data-stage", stage.key);

    const label = document.createElement("span");
    label.className = "stats-item-label";
    label.textContent = stage.label;

    const value = document.createElement("span");
    value.className = "stats-item-value";
    value.setAttribute("data-role", "stat-" + stage.key);
    value.textContent = String(stats.counts[stage.key]);

    li.appendChild(label);
    li.appendChild(value);
    el.statsGrid.appendChild(li);
  });
}

function renderFilterChips() {
  el.chips.forEach((chip) => {
    const active = chip.getAttribute("data-filter") === filterStage;
    chip.classList.toggle("is-active", active);
    chip.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function buildRecordCard(record) {
  const li = document.createElement("li");
  li.className = "record-card";
  li.setAttribute("data-stage", normalizeStage(record.stage));
  li.setAttribute("data-id", record.id);

  const top = document.createElement("div");
  top.className = "record-top";

  const info = document.createElement("div");
  const company = document.createElement("h3");
  company.className = "record-company";
  company.textContent = record.company || "未填写公司";
  const position = document.createElement("p");
  position.className = "record-position";
  position.textContent = record.position || "未填写岗位";
  info.appendChild(company);
  info.appendChild(position);

  const badge = document.createElement("span");
  badge.className = "stage-badge";
  badge.setAttribute("data-stage", normalizeStage(record.stage));
  badge.textContent = STAGE_LABEL[normalizeStage(record.stage)];

  top.appendChild(info);
  top.appendChild(badge);

  const meta = document.createElement("p");
  meta.className = "record-meta";
  meta.textContent = "投递日期：" + formatDate(record.applyDate);

  li.appendChild(top);
  li.appendChild(meta);

  if (record.note) {
    const note = document.createElement("p");
    note.className = "record-note";
    note.textContent = record.note;
    li.appendChild(note);
  }

  const actions = document.createElement("div");
  actions.className = "record-actions";

  const editBtn = document.createElement("button");
  editBtn.type = "button";
  editBtn.className = "btn btn-edit";
  editBtn.setAttribute("data-action", "edit");
  editBtn.setAttribute("data-id", record.id);
  editBtn.textContent = "编辑";

  const deleteBtn = document.createElement("button");
  deleteBtn.type = "button";
  deleteBtn.className = "btn btn-delete";
  deleteBtn.setAttribute("data-action", "delete");
  deleteBtn.setAttribute("data-id", record.id);
  deleteBtn.textContent = "删除";

  actions.appendChild(editBtn);
  actions.appendChild(deleteBtn);
  li.appendChild(actions);

  return li;
}

function renderList() {
  const visible = filterStage === "all"
    ? records.slice()
    : records.filter((record) => normalizeStage(record.stage) === filterStage);

  el.recordList.textContent = "";
  visible.forEach((record) => {
    el.recordList.appendChild(buildRecordCard(record));
  });

  el.listCount.textContent = visible.length + " 条";
  el.emptyHint.hidden = visible.length > 0;
  el.emptyHint.textContent = records.length === 0
    ? "还没有投递记录，先在上方添加一条吧。"
    : "当前筛选阶段下没有记录。";
}

function render() {
  renderStats();
  renderFilterChips();
  renderList();
}

function resetForm() {
  editingId = null;
  el.company.value = "";
  el.position.value = "";
  el.date.value = todayISO();
  el.stage.value = "pending";
  el.note.value = "";
  el.company.classList.remove("is-invalid");
  showFormError("");
  el.formTitle.textContent = "新增投递记录";
  el.submitBtn.textContent = "新增记录";
  el.cancelBtn.hidden = true;
}

function startEdit(id) {
  const record = records.find((item) => item.id === id);
  if (!record) return;
  editingId = id;
  el.company.value = record.company;
  el.position.value = record.position;
  el.date.value = record.applyDate;
  el.stage.value = normalizeStage(record.stage);
  el.note.value = record.note;
  el.company.classList.remove("is-invalid");
  showFormError("");
  el.formTitle.textContent = "编辑投递记录";
  el.submitBtn.textContent = "保存修改";
  el.cancelBtn.hidden = false;
  if (typeof el.company.focus === "function") el.company.focus();
}

async function persist(nextRecords) {
  const next = Object.assign({}, state);
  next[STORE_KEY] = nextRecords;
  await appStore.setState(next);
  state = next;
  records = nextRecords;
}

async function handleSubmit(event) {
  event.preventDefault();
  const company = el.company.value.trim();
  const position = el.position.value.trim();
  const applyDate = el.date.value;
  const stage = normalizeStage(el.stage.value);
  const note = el.note.value.trim();

  if (!company) {
    el.company.classList.add("is-invalid");
    showFormError("请填写公司名称后再保存。");
    if (typeof el.company.focus === "function") el.company.focus();
    return;
  }
  el.company.classList.remove("is-invalid");
  showFormError("");

  let nextRecords;
  if (editingId) {
    nextRecords = records.map((record) => {
      if (record.id !== editingId) return record;
      return Object.assign({}, record, {
        company: company,
        position: position,
        applyDate: applyDate,
        stage: stage,
        note: note
      });
    });
  } else {
    nextRecords = records.concat([
      {
        id: createId(),
        company: company,
        position: position,
        applyDate: applyDate,
        stage: stage,
        note: note
      }
    ]);
  }

  try {
    await persist(nextRecords);
  } catch (error) {
    showFormError("保存失败，请重试。输入内容已保留。");
    return;
  }

  resetForm();
  render();
}

function openConfirmDialog(record) {
  el.dialogTitle.textContent = "确认删除";
  el.dialogText.textContent = "确定要删除「" + (record.company || "未填写公司") + "」这条投递记录吗？删除后无法恢复。";
  el.dialogMask.hidden = false;
  if (typeof el.dialogCancel.focus === "function") el.dialogCancel.focus();
  return new Promise((resolve) => {
    dialogResolver = resolve;
  });
}

function closeConfirmDialog(result) {
  el.dialogMask.hidden = true;
  const resolver = dialogResolver;
  dialogResolver = null;
  pendingDeleteId = null;
  if (resolver) resolver(result);
}

async function handleDelete(id) {
  const record = records.find((item) => item.id === id);
  if (!record) return;
  pendingDeleteId = id;
  const confirmed = await openConfirmDialog(record);
  if (!confirmed) return;
  if (pendingDeleteId !== id) return;

  const nextRecords = records.filter((item) => item.id !== id);
  try {
    await persist(nextRecords);
  } catch (error) {
    showFormError("删除失败，请重试。");
    return;
  }
  if (editingId === id) resetForm();
  render();
}

function bindEvents() {
  el.form.addEventListener("submit", handleSubmit);

  el.cancelBtn.addEventListener("click", () => {
    resetForm();
  });

  el.recordList.addEventListener("click", (event) => {
    const target = event.target;
    if (!target || typeof target.closest !== "function") return;
    const button = target.closest("button[data-action]");
    if (!button) return;
    const id = button.getAttribute("data-id");
    const action = button.getAttribute("data-action");
    if (action === "edit") {
      startEdit(id);
    } else if (action === "delete") {
      handleDelete(id);
    }
  });

  el.chips.forEach((chip) => {
    chip.addEventListener("click", () => {
      filterStage = chip.getAttribute("data-filter") || "all";
      render();
    });
  });

  el.dialogCancel.addEventListener("click", () => closeConfirmDialog(false));
  el.dialogConfirm.addEventListener("click", () => closeConfirmDialog(true));
  el.dialogMask.addEventListener("click", (event) => {
    if (event.target === el.dialogMask) closeConfirmDialog(false);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !el.dialogMask.hidden) closeConfirmDialog(false);
  });
}

async function init() {
  const loaded = await appStore.getState();
  state = loaded && typeof loaded === "object" ? loaded : {};

  if (!Object.prototype.hasOwnProperty.call(state, STORE_KEY) || !Array.isArray(state[STORE_KEY])) {
    const seeded = Object.assign({}, state);
    seeded[STORE_KEY] = [];
    await appStore.setState(seeded);
    state = seeded;
  }

  records = state[STORE_KEY].map(normalizeRecord);
  bindEvents();
  resetForm();
  render();
}

await init();

artifact.css:
:root {
  --blue-900: #0f2a5c;
  --blue-700: #1a4fa0;
  --blue-600: #2563eb;
  --blue-500: #3b82f6;
  --blue-100: #dbeafe;
  --blue-50: #eff6ff;
  --white: #ffffff;
  --ink: #10233f;
  --ink-soft: #4a5b74;
  --line: #d8e3f5;
  --danger: #d92d20;
  --danger-soft: #fee4e2;
  --shadow: 0 6px 18px rgba(15, 42, 92, 0.08);
  --radius: 14px;
}

#app {
  min-height: 100vh;
  background: linear-gradient(180deg, #eaf2ff 0%, #f7faff 45%, #ffffff 100%);
  color: var(--ink);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  -webkit-text-size-adjust: 100%;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 18px 14px 48px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.app-header {
  padding: 6px 4px 2px;
}

.app-title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  color: var(--blue-900);
  letter-spacing: 0.5px;
}

.app-subtitle {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 14px;
}

.panel-title {
  margin: 0 0 10px;
  font-size: 16px;
  font-weight: 600;
  color: var(--blue-900);
}

/* 统计 */
.stats-panel {
  background: linear-gradient(135deg, var(--blue-700) 0%, var(--blue-500) 100%);
  border-color: transparent;
  color: var(--white);
}

.stats-total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-bottom: 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.28);
}

.stats-total-label {
  font-size: 14px;
  opacity: 0.92;
}

.stats-total-value {
  font-size: 28px;
  font-weight: 700;
  line-height: 1;
}

.stats-grid {
  list-style: none;
  margin: 12px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.stats-item {
  background: rgba(255, 255, 255, 0.16);
  border-radius: 10px;
  padding: 8px 6px;
  text-align: center;
}

.stats-item-label {
  display: block;
  font-size: 12px;
  opacity: 0.92;
  white-space: nowrap;
}

.stats-item-value {
  display: block;
  font-size: 18px;
  font-weight: 700;
  margin-top: 2px;
}

/* 表单 */
.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 12px;
  min-width: 0;
}

.field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-soft);
}

.required {
  color: var(--danger);
}

.field input,
.field select,
.field textarea {
  width: 100%;
  font: inherit;
  color: var(--ink);
  background: var(--blue-50);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 10px 12px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.field textarea {
  resize: vertical;
  min-height: 68px;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  background: var(--white);
  border-color: var(--blue-500);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.18);
}

.field input.is-invalid {
  border-color: var(--danger);
  background: #fff6f5;
}

.form-error {
  margin: 0 0 10px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--danger-soft);
  color: #912018;
  font-size: 13px;
}

.form-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  font: inherit;
  font-weight: 600;
  border-radius: 10px;
  border: 1px solid transparent;
  padding: 10px 16px;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, opacity 0.15s ease;
}

.btn-primary {
  background: var(--blue-600);
  color: var(--white);
  flex: 1 1 140px;
}

.btn-primary:hover {
  background: var(--blue-700);
}

.btn-ghost {
  background: var(--white);
  color: var(--blue-700);
  border-color: var(--blue-100);
}

.btn-ghost:hover {
  background: var(--blue-50);
}

.btn-danger {
  background: var(--danger);
  color: var(--white);
}

.btn-danger:hover {
  background: #b42318;
}

.btn:focus-visible {
  outline: 2px solid var(--blue-700);
  outline-offset: 2px;
}

/* 列表 */
.list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.list-head .panel-title {
  margin-bottom: 0;
}

.list-count {
  font-size: 13px;
  color: var(--ink-soft);
  background: var(--blue-50);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 2px 10px;
  white-space: nowrap;
}

.filter-bar {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 12px 0 4px;
  -webkit-overflow-scrolling: touch;
}

.chip {
  font: inherit;
  font-size: 13px;
  white-space: nowrap;
  padding: 6px 14px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--blue-50);
  color: var(--blue-700);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.chip:hover {
  border-color: var(--blue-500);
}

.chip.is-active {
  background: var(--blue-600);
  border-color: var(--blue-600);
  color: var(--white);
}

.record-list {
  list-style: none;
  margin: 8px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record-card {
  border: 1px solid var(--line);
  border-left: 4px solid var(--blue-500);
  border-radius: 12px;
  padding: 12px;
  background: var(--white);
}

.record-card[data-stage="pending"] {
  border-left-color: #94a3b8;
}

.record-card[data-stage="applied"] {
  border-left-color: var(--blue-500);
}

.record-card[data-stage="interview"] {
  border-left-color: #f59e0b;
}

.record-card[data-stage="closed"] {
  border-left-color: #64748b;
}

.record-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--blue-900);
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
  word-break: break-word;
}

.stage-badge {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 999px;
  white-space: nowrap;
}

.stage-badge[data-stage="pending"] {
  background: #eef2f7;
  color: #475569;
}

.stage-badge[data-stage="applied"] {
  background: var(--blue-100);
  color: var(--blue-700);
}

.stage-badge[data-stage="interview"] {
  background: #fef3c7;
  color: #92400e;
}

.stage-badge[data-stage="closed"] {
  background: #e2e8f0;
  color: #475569;
}

.record-meta {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--ink-soft);
}

.record-note {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--ink);
  background: var(--blue-50);
  border-radius: 8px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  margin-top: 10px;
}

.record-actions .btn {
  padding: 7px 14px;
  font-size: 13px;
}

.btn-edit {
  background: var(--blue-50);
  color: var(--blue-700);
  border-color: var(--blue-100);
}

.btn-edit:hover {
  background: var(--blue-100);
}

.btn-delete {
  background: var(--white);
  color: var(--danger);
  border-color: var(--danger-soft);
}

.btn-delete:hover {
  background: var(--danger-soft);
}

.empty-hint {
  margin: 14px 0 4px;
  text-align: center;
  font-size: 13px;
  color: var(--ink-soft);
}

/* 对话框 */
.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(15, 42, 92, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-mask[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 340px;
  background: var(--white);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: 0 18px 40px rgba(15, 42, 92, 0.28);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  color: var(--blue-900);
}

.dialog-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--ink-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

@media (max-width: 420px) {
  .stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .field-row {
